def finish(g,inp,start,a,b,length,half,rise,datum,valid,sid,cell,*,local_frames):
    rows=inp.outputs['Approaches'];mouths=inp.outputs['Mouths']
    mouth=lambda key,kind='FLOAT':c._read(g,mouths,'st_cj_'+key,start,kind)
